    assert_eq(field(checkout, "scope"), Some(Json::string("build-checkout")))
    assert_eq(field(field(checkout, "actualCommit").unwrap(), "value"), Some(Json::string(head)))
    assert_eq(field(checkout, "matches"), Some(Json::boolean(true)))
    assert_eq(field(create_event(events, "create-attempt"), "status"), Some(Json::string("success")))
    for event in events {
      if field(event, "createAttempt") is Some(_) {
        assert_eq(field(event, "runId"), field(received, "runId"))
      }
    }
    let raw = @fs.read_file(directory + "/.local/state/orca-env-devsy/events.jsonl").text()
    assert_false(raw.contains("privacy-secret"))
